from collections import deque
from typing import List, Tuple

def f(inputs: List[Tuple[int, int, List[Tuple[int, int]], List[Tuple[int, int]]]]):
    def bfs(graph, start, end):
        visited = [False] * len(graph)
        queue = deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for i in graph[node]:
                if not visited[i]:
                    queue.append(i)
                    visited[i] = True
                if i == end:
                    return True
        return False

    res = []
    for c, w, points, edges in inputs:
        if c == 0 and w == 0:
            break
        graph = [[] for _ in range(c)]
        for u, v in edges:
            graph[u - 1].append(v - 1)
            graph[v - 1].append(u - 1)
        for x1, y1 in points:
            for x2, y2 in points:
                if (x1!= x2 or y1!= y2) and bfs(graph, points.index((x1, y1)), points.index((x2, y2))):
                    res.append((x1, y1, x2, y2))
        res.append([])

    return res
```

